const inputItems = $input.all();

const TARGET_WORKFLOW_ID = 'BcaOXV68sc9d3cTp';
const TARGET_WORKFLOW_NAME = 'WhatsApp Live Two';
const THRESHOLD_MINUTES = 3;

let executions = [];

for (const item of inputItems) {
  const json = item.json ?? {};

  if (Array.isArray(json.data)) {
    executions = json.data;
    break;
  }

  if (Array.isArray(json.results)) {
    executions = json.results;
    break;
  }

  if (Array.isArray(json.executions)) {
    executions = json.executions;
    break;
  }

  if (json.id || json.startedAt || json.stoppedAt || json.createdAt || json.updatedAt) {
    executions.push(json);
  }
}

executions = executions
  .filter((execution) => String(execution.workflowId ?? execution.workflowData?.id ?? TARGET_WORKFLOW_ID) === TARGET_WORKFLOW_ID)
  .sort((a, b) => {
    const aDate = new Date(a.startedAt || a.stoppedAt || a.createdAt || a.updatedAt || 0).getTime();
    const bDate = new Date(b.startedAt || b.stoppedAt || b.createdAt || b.updatedAt || 0).getTime();
    return bDate - aDate;
  });

if (!executions.length) {
  return [{
    json: {
      workflowId: TARGET_WORKFLOW_ID,
      workflowName: TARGET_WORKFLOW_NAME,
      shouldReactivate: true,
      reason: 'No executions found for target workflow'
    }
  }];
}

const last = executions[0];
const rawDate = last.startedAt || last.stoppedAt || last.createdAt || last.updatedAt;

if (!rawDate) {
  return [{
    json: {
      workflowId: TARGET_WORKFLOW_ID,
      workflowName: TARGET_WORKFLOW_NAME,
      lastExecutionId: last.id,
      shouldReactivate: true,
      reason: 'Latest execution has no usable timestamp'
    }
  }];
}

const lastDate = new Date(rawDate);

if (Number.isNaN(lastDate.getTime())) {
  return [{
    json: {
      workflowId: TARGET_WORKFLOW_ID,
      workflowName: TARGET_WORKFLOW_NAME,
      lastExecutionId: last.id,
      rawTimestamp: rawDate,
      shouldReactivate: true,
      reason: 'Latest execution timestamp is invalid'
    }
  }];
}

const now = new Date();
const diffMinutes = (now.getTime() - lastDate.getTime()) / 1000 / 60;
const shouldReactivate = diffMinutes > THRESHOLD_MINUTES;

return [{
  json: {
    workflowId: TARGET_WORKFLOW_ID,
    workflowName: TARGET_WORKFLOW_NAME,
    lastExecutionId: last.id,
    lastStartedAt: lastDate.toISOString(),
    diffMinutes,
    shouldReactivate,
    reason: shouldReactivate
      ? `Target workflow appears stalled. Last execution was ${diffMinutes.toFixed(2)} minutes ago.`
      : `Target workflow is healthy. Last execution was ${diffMinutes.toFixed(2)} minutes ago.`
  }
}];

const item = $input.first();
const json = item?.json ?? {};

if (json.error || json.message?.includes?.('error')) {
  console.error('CRITICAL: WhatsApp Live Two was deactivated but could not be activated again. Manual action is required immediately.', json);
  return [{
    json: {
      status: 'critical_activation_failed',
      workflowId: 'BcaOXV68sc9d3cTp',
      workflowName: 'WhatsApp Live Two',
      message: 'CRITICAL: WhatsApp Live Two was deactivated but could not be activated again. Manual action required.',
      activateResponse: json
    }
  }];
}

console.log('[REACTIVATED] WhatsApp Live Two scheduler appeared stalled. The workflow was automatically deactivated and activated again.', json);
return [{
  json: {
    status: 'reactivated',
    workflowId: 'BcaOXV68sc9d3cTp',
    workflowName: 'WhatsApp Live Two',
    message: 'Alert: WhatsApp Live Two scheduler appeared stalled. The workflow was automatically deactivated and activated again.',
    activateResponse: json
  }
}];
